"""Supplementary figure with the schematic of the cross-feeding use case (glucose -> C. beijerinckii -> H2 and acetate -> M. barkeri -> methane): the panel A of the submitted Fig. 6, cropped from assets/schematic_source_main_fig_6_submitted.png (the drawing is not generated by the simulations).
usage: make_schematic.py SOURCE.png OUT.png"""
import sys, matplotlib.image as mpimg, matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
im = mpimg.imread(sys.argv[1]); H, W = im.shape[:2]; c = im[: int(0.365 * H), : int(0.56 * W)].copy(); c[: int(0.09 * c.shape[0]), : int(0.045 * c.shape[1])] = 1   # the panel letter of the submitted figure is removed
fig = plt.figure(figsize=(c.shape[1] / 300, c.shape[0] / 300), dpi=300); ax = fig.add_axes([0, 0, 1, 1]); ax.imshow(c); ax.axis("off"); fig.savefig(sys.argv[2], dpi=300, facecolor="white")
